const body = $json.body ?? $json;
const payload = body.payload ?? {};
const ml = body.ml_prediction ?? payload.ml_prediction ?? {};
const alertId = body.alert_id ?? body.id ?? payload.alert_id ?? 'unknown-alert';
const severity = String(body.severity ?? payload.severity ?? 'unknown').toLowerCase();
const title = body.title ?? payload.title ?? payload.reason ?? 'SOC alert';
const description = body.description ?? payload.description ?? title;
const srcIp = body.src_ip ?? payload.src_ip ?? body.target ?? null;
const dstIp = body.dst_ip ?? payload.dst_ip ?? null;
const dstPort = body.dst_port ?? payload.dst_port ?? null;
const eventType = body.event_type ?? payload.event_type ?? null;
const confidence = body.confidence ?? payload.confidence ?? ml.confidence ?? null;
const mitre = body.mitre ?? payload.mitre ?? ml.mitre ?? [];
const reasons = body.reasons ?? payload.reasons ?? [];
const recommendations = body.recommendations ?? payload.recommendations ?? [];

const evidenceText = [
  body.attack_type,
  payload.attack_type,
  ml.attack_type,
  title,
  description,
  eventType,
  JSON.stringify(mitre),
  JSON.stringify(reasons),
].join(' ').toLowerCase();

function classifyAttack(text) {
  const direct = String(body.attack_type ?? payload.attack_type ?? ml.attack_type ?? '').toLowerCase();
  if (direct && direct !== 'null' && direct !== 'undefined') return direct;
  if (/http.*flood|goldeneye|slowloris|ddos|\bdos\b|syn flood|udp flood|icmp flood/.test(text)) return 'http_flood_dos';
  if (/sqlmap|sql injection|union select|sleep\(|\bid=1%27/.test(text)) return 'sql_injection_probe';
  if (/nmap|port scan|network service discovery|vulnerability scan|ping sweep|recon/.test(text)) return 'network_scan';
  if (/brute|4625|failed logon|failed password|ssh/.test(text)) return 'brute_force';
  if (/1102|audit log.*cleared/.test(text)) return 'windows_log_cleared';
  if (/powershell|-enc|frombase64string|downloadstring|invoke-expression|\biex\b/.test(text)) return 'powershell_execution';
  if (/arp spoof|ip spoof|mitm|impersonation/.test(text)) return 'mitm_spoofing';
  if (/mirai|botnet/.test(text)) return 'mirai_malware';
  if (/\.env|phpmyadmin|wp-admin|nikto|dirb/.test(text)) return 'web_sensitive_path';
  return 'security_event';
}

const attackType = classifyAttack(evidenceText);
const attackBook = {
  http_flood_dos: { name: 'HTTP Flood / DoS', mitre: 'T1498 / T1499', priority: 'Kh?n c?p: ki?m tra OPNsense states, throughput v? web service.' },
  sql_injection_probe: { name: 'SQL Injection Probe', mitre: 'T1190', priority: 'Ki?m tra access.log, query string v? ?ng d?ng web.' },
  network_scan: { name: 'Network Reconnaissance / Port Scan', mitre: 'T1046 / T1595.002', priority: 'X?c minh Kali/lab scanner; n?u kh?ng h?p l? th? ch?n ngu?n.' },
  brute_force: { name: 'Brute Force Authentication', mitre: 'T1110', priority: 'Ki?m tra th?t b?i ??ng nh?p v? ??ng nh?p th?nh c?ng sau ??.' },
  windows_log_cleared: { name: 'Windows Audit Log Cleared', mitre: 'T1070.001', priority: '?u ti?n cao: ki?m tra d?u hi?u x?a d?u v?t tr?n endpoint.' },
  powershell_execution: { name: 'Suspicious PowerShell Execution', mitre: 'T1059.001', priority: 'Thu th?p command line, parent process v? telemetry endpoint.' },
  mitm_spoofing: { name: 'MITM / Spoofing Activity', mitre: 'T1557', priority: 'Ki?m tra ARP table, gateway impersonation v? network segment.' },
  mirai_malware: { name: 'Mirai-like IoT Malware', mitre: 'T1498', priority: 'C? l?p thi?t b? IoT nghi nhi?m v? ki?m tra outbound scan/flood.' },
  web_sensitive_path: { name: 'Sensitive Web Path Discovery', mitre: 'T1190', priority: 'Ki?m tra truy c?p .env/admin/phpMyAdmin v? c?u h?nh web.' },
  security_event: { name: 'Security Event', mitre: 'Not mapped', priority: 'X?c minh log g?c v? t??ng quan v?i alert trong A11 SOC.' },
};
const attack = attackBook[attackType] ?? attackBook.security_event;
const route = ['critical', 'high'].includes(severity) ? 'soc_hot_queue' : 'soc_watch_queue';
const toEmail = $env.A11_SOC_ALERT_EMAIL_TO || 'soc-analyst@a11.local';
const fromEmail = $env.A11_SOC_ALERT_EMAIL_FROM || 'a11-soc@a11.local';
const subject = `[A11 SOC][${severity.toUpperCase()}][${attackType}] ${title}`;
const mitreText = Array.isArray(mitre) && mitre.length ? mitre.map((item) => `${item.id || ''} ${item.name || ''}`.trim()).join(', ') : attack.mitre;
const reasonText = Array.isArray(reasons) && reasons.length ? reasons.map((item) => `- ${item}`).join('\n') : '- No detailed triage reason supplied.';
const recText = Array.isArray(recommendations) && recommendations.length ? recommendations.map((item) => `- ${item}`).join('\n') : '- Validate the alert against raw telemetry.';
function esc(value) {
  return String(value ?? '').replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;' }[char]));
}
const textBody = `A11 SOC ALERT\n\nAlert ID: ${alertId}\nSeverity: ${severity.toUpperCase()}\nAttack type: ${attackType} - ${attack.name}\nConfidence: ${confidence ?? 'n/a'}\nMITRE: ${mitreText}\nSource: ${srcIp ?? 'unknown'}\nDestination: ${dstIp ?? 'unknown'}:${dstPort ?? '-'}\nEvent type: ${eventType ?? 'unknown'}\nRoute: ${route}\n\nAssessment:\n${description}\n\nReasons:\n${reasonText}\n\nRecommendations:\n${recText}\n\nAutomation note: Email generated by n8n after A11 SOC triage/ML/RAG.`;
const htmlBody = `<h2>A11 SOC Alert</h2><table border="1" cellpadding="6" cellspacing="0"><tr><td><b>Alert ID</b></td><td>${esc(alertId)}</td></tr><tr><td><b>Severity</b></td><td>${esc(severity.toUpperCase())}</td></tr><tr><td><b>Attack type</b></td><td>${esc(attackType)} - ${esc(attack.name)}</td></tr><tr><td><b>Confidence</b></td><td>${esc(confidence ?? 'n/a')}</td></tr><tr><td><b>MITRE</b></td><td>${esc(mitreText)}</td></tr><tr><td><b>Source</b></td><td>${esc(srcIp ?? 'unknown')}</td></tr><tr><td><b>Destination</b></td><td>${esc(dstIp ?? 'unknown')}:${esc(dstPort ?? '-')}</td></tr><tr><td><b>Event type</b></td><td>${esc(eventType ?? 'unknown')}</td></tr></table><h3>Assessment</h3><p>${esc(description)}</p><h3>n8n attack analysis</h3><p>${esc(attack.priority)}</p><h3>Reasons</h3><pre>${esc(reasonText)}</pre><h3>Recommendations</h3><pre>${esc(recText)}</pre>`;
return [{
  json: {
    response: {
      ok: true,
      workflow: 'A11 SOC Local Automation',
      kind: 'alert_notification',
      alert_id: String(alertId),
      severity,
      route,
      attack_type: attackType,
      email_to: toEmail,
    },
    audit: {
      actor: 'n8n',
      action: 'automation.notification_received',
      object_type: 'alert',
      object_id: String(alertId),
      outcome: 'success',
      detail: {
        workflow: 'A11 SOC Local Automation',
        stage: 'n8n_attack_analysis_email',
        severity,
        title,
        src_ip: srcIp,
        dst_ip: dstIp,
        dst_port: dstPort,
        event_type: eventType,
        attack_type: attackType,
        attack_name: attack.name,
        mitre: mitreText,
        confidence,
        route,
        email: { to: toEmail, subject, sink: 'mailpit' },
        received_at: new Date().toISOString(),
        original_payload: body,
      },
    },
    email: {
      From: { Email: fromEmail, Name: 'A11 Agentic SOC' },
      To: [{ Email: toEmail, Name: 'SOC Analyst' }],
      Subject: subject,
      Text: textBody,
      HTML: htmlBody,
      Tags: ['A11 SOC', severity, attackType],
      Headers: { 'X-A11-Alert-ID': String(alertId), 'X-A11-Attack-Type': attackType },
    },
  },
}];

const body = $json.body ?? $json;
const payload = body.payload ?? {};
const actionType = body.action_type ?? payload.action_type ?? 'unknown_action';
const target = body.target ?? payload.target ?? null;
const alertId = payload.alert_id ?? body.alert_id ?? target ?? 'unknown-action';
const severity = String(payload.severity ?? body.severity ?? 'unknown').toLowerCase();
const attackType = String(payload.attack_type ?? body.attack_type ?? 'security_event').toLowerCase();
const reason = payload.reason ?? body.reason ?? payload.title ?? 'Approved SOC response action';
const mitre = payload.mitre ?? body.mitre ?? [];
const allowedLocalActions = ['notify_soc', 'block_ip', 'isolate_host'];
const supported = allowedLocalActions.includes(actionType);
const outcome = supported ? 'success' : 'failed';
const toEmail = $env.A11_SOC_ALERT_EMAIL_TO || 'soc-analyst@a11.local';
const fromEmail = $env.A11_SOC_ALERT_EMAIL_FROM || 'a11-soc@a11.local';
const subject = `[A11 SOC RESPONSE][${actionType}] ${target ?? alertId}`;
const mitreText = Array.isArray(mitre) && mitre.length ? mitre.map((item) => `${item.id || ''} ${item.name || ''}`.trim()).join(', ') : 'Not mapped';
function esc(value) {
  return String(value ?? '').replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;' }[char]));
}
const textBody = `A11 SOC RESPONSE ACTION\n\nAlert/Action ID: ${alertId}\nAction: ${actionType}\nTarget: ${target ?? 'n/a'}\nSeverity: ${severity}\nAttack type: ${attackType}\nMITRE: ${mitreText}\nSupported by n8n: ${supported}\n\nReason:\n${reason}\n\nAutomation note: This email was generated by n8n after the SOC response workflow was invoked.`;
const htmlBody = `<h2>A11 SOC Response Action</h2><table border="1" cellpadding="6" cellspacing="0"><tr><td><b>Alert/Action ID</b></td><td>${esc(alertId)}</td></tr><tr><td><b>Action</b></td><td>${esc(actionType)}</td></tr><tr><td><b>Target</b></td><td>${esc(target ?? 'n/a')}</td></tr><tr><td><b>Severity</b></td><td>${esc(severity)}</td></tr><tr><td><b>Attack type</b></td><td>${esc(attackType)}</td></tr><tr><td><b>MITRE</b></td><td>${esc(mitreText)}</td></tr><tr><td><b>Supported</b></td><td>${esc(supported)}</td></tr></table><h3>Reason</h3><p>${esc(reason)}</p>`;
return [{
  json: {
    response: {
      ok: supported,
      mode: 'n8n_webhook',
      workflow: 'A11 SOC Local Automation',
      action_type: actionType,
      target,
      attack_type: attackType,
      email_to: toEmail,
      message: supported
        ? 'Action accepted by local n8n workflow, analyzed, emailed and recorded in SOC audit.'
        : 'Unsupported action type for local n8n workflow.',
    },
    audit: {
      actor: 'n8n',
      action: 'automation.response_webhook',
      object_type: 'response_action',
      object_id: String(alertId),
      outcome,
      detail: {
        workflow: 'A11 SOC Local Automation',
        stage: 'n8n_response_email',
        action_type: actionType,
        target,
        severity,
        attack_type: attackType,
        mitre: mitreText,
        payload,
        email: { to: toEmail, subject, sink: 'mailpit' },
        received_at: new Date().toISOString(),
        supported,
      },
    },
    email: {
      From: { Email: fromEmail, Name: 'A11 Agentic SOC' },
      To: [{ Email: toEmail, Name: 'SOC Analyst' }],
      Subject: subject,
      Text: textBody,
      HTML: htmlBody,
      Tags: ['A11 SOC', 'response', actionType, attackType],
      Headers: { 'X-A11-Action-Type': actionType, 'X-A11-Attack-Type': attackType },
    },
  },
}];
